#!/usr/bin/env python3
"""Render exhaustive configuration defaults from the maintained schema."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
DETAILS={
'PLOT_LOOP_VOLCANO':'Report biological differential loop P values versus edgeR log2 allocation effects when inferential results exist; descriptive runs explain absence.',
'VOLCANO_MIN_ABS_LOG2_EFFECT':'Nonnegative effect magnitude for highlighting only; does not filter points, change tests, or recompute BH FDR.',
'VOLCANO_LABEL_TOP_N':'Label up to this many highlighted loops by model P value; 0 disables labels, maximum 20. All usable tested points remain plotted.',
'RUN_TADS':'Insulation-defined per-replicate/condition domains and descriptive event comparisons; active with insulation.',
'AGGREGATE_MODULES':'Comma-separated apa,ada,saddle selection; only chosen aggregate consumers run.',
'INSULATION_BOUNDARY_THRESHOLD':'Li (existing default), Otsu, or a finite nonnegative fixed prominence threshold; numbers use cooltools strength units.',
'TAD_MIN_LENGTH_BP':'Minimum boundary-to-boundary domain length in bp; descriptive policy.',
'TAD_MAX_LENGTH_BP':'Maximum boundary-to-boundary domain length in bp; descriptive policy.',
'TAD_BOUNDARY_TOLERANCE_BP':'Complete-span consensus and boundary matching tolerance in bp.',
'TAD_MIN_REPLICATE_FRACTION':'Minimum fraction of biological observations supporting each condition domain/evaluable region; rounded up.',
'TAD_MIN_RECIPROCAL_OVERLAP':'Minimum overlap divided by each interval length for a one-to-one match.',
'TAD_SIZE_CHANGE_BP':'Minimum absolute length change in bp; growth/shrinkage must also exceed the fractional threshold.',
'TAD_SIZE_CHANGE_FRACTION':'Minimum absolute fractional length change relative to reference.',
'TAD_STRENGTH_CHANGE':'Minimum absolute case-minus-reference change in mean endpoint boundary prominence for an otherwise geometrically stable matched domain; descriptive annotation, not intra-domain contact strength.',
'TAD_SENSITIVITY_THRESHOLDS':'Alternative fixed boundary thresholds for complete TAD call/event sensitivity; same score grid, no matrix copies.',
'PIPELINE_NAME':'Workflow identity; keep microc2compare.',
'SCHEMA_VERSION':'Configuration schema version; v0.1 accepts 1.',
'PROJECT':'Safe project identifier, matching every sample row.',
'ANALYSIS_SET_ID':'Stable name for the complete common analysis set.',
'RUN_ID':'Stable explicit run identity; change for a new historical run.',
'REFERENCE_ID':'Registered assembly/reference identity; must match every sample.',
'ANALYSIS_MODE':'within_assay or explicit descriptive assay_comparison.',
'SAMPLESHEET':'Biological observations CSV/TSV; one consolidated map per unit/condition.',
'TECHNICAL_MEMBERSHIP':'Technical library/source/deduplication TSV.',
'COMPARISONS':'Explicit contrasts, design, inference mode and module table.',
'REFERENCE_REGISTRY':'Immutable reference JSON/YAML with asset checksums.',
'INDEPENDENT_FEATURES_REGISTRY':'Frozen external independent loop registry; required for formal/preliminary loops.',
'OUTDIR':'Owned results base; appends project/analysis/run identifiers.',
'SCRATCH_ROOT':'Owned temporary base; task-scoped TMPDIR, never imported data.',
'RANDOM_SEED':'Recorded PCG64 sensitivity/calibration base seed.',
'PYTHON_BOOTSTRAP':'Python 3.11+ executable for dependency-free metadata, and explicit development helpers.',
'CONDA_EXE':'Registered Conda executable; no solve/update during analyses.',
'ENVIRONMENT_MODE':'reuse immutable checked prefixes; locked rejects drift/missing locks; development explicitly uses local Python/R.',
'CORE_ENV_PREFIX':'Checked core scientific Conda prefix.',
'HICREP_ENV_PREFIX':'Checked separate HiCRep Conda prefix, or a compatible checked shared prefix.',
'DIFF_R_ENV_PREFIX':'Checked R/edgeR/limma prefix; needed only for inferential comparisons.',
'CORE_LOCK':'Explicit tested Linux Conda lock, with matching .inventory.json in locked mode.',
'HICREP_LOCK':'Explicit HiCRep lock; pip wheel artifacts must also be installed/verified separately.',
'DIFF_R_LOCK':'Explicit tested R Conda lock, with matching .inventory.json in locked mode.',
'R_SCRIPT':'Rscript executable used only in explicit development mode.',
'RUN_QC':'Contact summaries and raw/balanced P(s); required by loops/aggregates/sensitivity.',
'RUN_HICREP':'Pairwise concordance task at the QC barrier even if balanced QC is disabled; also in enabled depth sensitivity.',
'RUN_POOL':'Optional pool discovery maps; default false, no core dependency.',
'POOL_MODE':'import existing validated pools, or explicit create for missing requested scopes.',
'POOLS_MANIFEST':'Optional pool membership/URI/provenance table; mandatory for import mode.',
'RUN_DEPTH_SENSITIVITY':'Optional descriptive seeded contact thinning; default false.',
'DEPTH_SENSITIVITY_MODE':'raw_only P(s)/HiCRep, or explicit balanced_features fixed-loop/insulation summaries.',
'BALANCE_NEW_DERIVED_MAPS':'Allows balancing genuinely changed task-owned optional maps only; alone launches no task.',
'RUN_COMPARTMENTS':'Oriented eigenvectors at the configured compartment grid; needs phasing track.',
'RUN_INSULATION':'Fixed-grid insulation and per-window boundary calls.',
'RUN_LOOPS':'Dots discovery at the primary and approved sensitivity grid.',
'RUN_AGGREGATES':'Per-replicate APA/ADA/saddles using enabled feature consumers.',
'RUN_DIFFERENTIAL':'Explicit comparison adapters; formal requests retain all statistical gates.',
'RUN_FINAL_REPORT':'Standalone HTML, plots, methods and downloadable outputs.',
'KEEP_POOLED_MAPS':'Retain newly created pool maps after consumers; imported pools always stay untouched.',
'KEEP_DOWNSAMPLED_MAPS':'Retain explicitly generated sensitivity maps instead of releasing after each seed.',
'CLEAN_SCRATCH_ON_SUCCESS':'Remove only the successful task-owned scratch directory.',
'COMPARTMENT_RESOLUTION':'Existing input group for eigenvectors; v0.1 scientific default 100 kb.',
'INSULATION_RESOLUTION':'Existing input fixed score grid; v0.1 default 10 kb.',
'INSULATION_WINDOWS_BP':'Comma-separated positive grid-multiple windows; includes primary.',
'INSULATION_PRIMARY_WINDOW_BP':'Single primary differential insulation family; default 100 kb.',
'INSULATION_MIN_VALID_PIXEL_FRACTION':'Prespecified eligible/full-diamond pixel coverage threshold.',
'INSULATION_IGNORE_DIAGS':'Ignored diagonals for expected/insulation and explicit new-map balancing.',
'LOOP_RESOLUTION':'Primary single-bin loop grid; default 10 kb.',
'LOOP_SENSITIVITY_RESOLUTIONS':'Empty or 5000 only; requires existing grid and documented approval.',
'FINE_RESOLUTION_QC_APPROVED':'Explicit 5-kb coverage/balance/depth review gate; no universal threshold is implied.',
'LOOP_CALLER':'cooltools_dots; other callers are unsupported.',
'LOOP_MIN_DISTANCE_BP':'Inclusive same-view cis lower bound for calls/counts/exposure.',
'LOOP_MAX_DISTANCE_BP':'Inclusive same-view cis upper bound for calls/counts/exposure.',
'LOOP_CONSENSUS_TOLERANCE_BINS':'Complete-linkage anchor tolerance in bins; default one, no transitive chaining.',
'LOOP_COUNT_WINDOW_BINS':'Single pixel only in v0.1; values other than one are rejected.',
'LOOP_MIN_TOTAL_COUNT':'Prespecified all-sample raw-count sum filter.',
'LOOP_MIN_MEAN_COUNT_AT_MIN_EXPOSURE':'Prespecified mean allocation times minimum exposure filter.',
'LOOP_MIN_FEATURES_FORMAL':'Minimum retained independent features before dispersion fitting.',
'LOOP_NORMALIZATION':'eligible_cis_exposure only; no TMM/weights/OE in the raw count model.',
'PS_RESOLUTION':'Existing input resolution for P(s) and basic domain registration.',
'HICREP_RESOLUTION':'Existing raw-count resolution for concordance.',
'HICREP_MAX_DISTANCE_BP':'Maximum SCC distance; views are combined by stratum weights.',
'HICREP_SMOOTHING_BINS':'Sparse smoothing half-width; its excluded-bin footprint is masked.',
'DOWNSAMPLING_REPEATS':'Inactive unless depth sensitivity is enabled; default five draws.',
'FDR_THRESHOLD':'Declared model BH threshold; calibration protocol currently fixes nominal 0.05.',
'FORMAL_MIN_UNITS_PER_CONDITION':'Minimum independent units for formal requests.',
'PRELIMINARY_MIN_UNITS_PER_CONDITION':'Explicit preliminary unit floor, still requires rank/df/calibration.',
'MIN_RESIDUAL_DF':'Residual degrees-of-freedom floor; policy requires at least two.',
'CALIBRATION_REGISTRY':'Hashed passing artifacts keyed to source/environment/module/design/recipe.',
'ALLOW_UNCALIBRATED_DEVELOPMENT':'Explicit fixture/method exception; outputs labeled uncalibrated, never release evidence.',
'WEIGHT_COLUMN':'Existing upstream bin column; never written to imported maps.',
'WEIGHT_CONVENTION':'Explicit multiplicative or divisive; divisive conversion is in memory.',
'LEGACY_WEIGHT_VALIDATION':'reject missing convergence, or explicit finite_positive exception with evidence gap.',
'SADDLE_PARTITION_SOURCE':'replicate_rank_mean, external registered track, or validated all_sample_pool.',
'SADDLE_REFERENCE_TRACK':'Exact-grid external bedGraph for the explicit external partition mode.',
'MIN_PHASING_CORRELATION':'Minimum absolute component/track correlation for orientation.',
'MAX_DENSE_BINS':'Bound on dense regional arrays; compartment memory estimate also applies.',
'PIXEL_CHUNKSIZE':'Raw pixel streaming/merge chunk size; tune with measured memory/I/O.',
'MIN_FREE_DISK_MB':'Minimum free-space floor near outputs/scratch; optional derived capacity needs pilot budgeting.',
'TOTAL_CPUS':'Conservative CPU admission budget within actual affinity/cgroup allocation.',
'MAX_MEMORY_MB':'Decimal MB admission budget within actual available physical/cgroup memory.',
'MAX_PARALLEL_JOBS':'Total homogeneous batch job cap.',
'MAX_PARALLEL_SAMPLES':'Biological-sample/batch cap; conservatively also limits run-level stages.',
'MAX_PARALLEL_MATRIX':'Cap on simultaneous matrix-heavy tasks.',
'MAX_PARALLEL_IO':'Cap on simultaneous registration/pool/thinning I/O-heavy tasks.'}

properties=json.loads((ROOT/'schemas/config.schema.json').read_text())['properties']
lines=['# Configuration reference','','On the shared server, copy project configurations into your own workspace and source the maintainer-controlled versioned site profile for checked software. Keep results/scratch outside the release; resource presets apply per run. See [shared user setup](16-shared-server-installation.md#3-start-as-an-ordinary-server-user).','','The project `.conf` is trusted Bash and is sourced after template defaults. Unknown uppercase assignments in that file are rejected; normalized allowed values are validated and snapshotted. This is a typo check, not a Bash security sandbox. Never source sample rows or an upstream configuration automatically.','','Relative configuration paths resolve against the project configuration directory. Manifest paths resolve against their own table directory. CLI `-s` resolves against the invocation directory. Source a resource preset explicitly, then place project overrides afterward. Missing optional paths are empty strings.','','```bash','source "/opt/conda_envs/microc2compare/releases/shared-design-json-fix-20261008/microc2compare-0.1.0/config/resources_pilot.conf"','PROJECT="experiment"','SAMPLESHEET="samples.csv"','TECHNICAL_MEMBERSHIP="technical_membership.tsv"','COMPARISONS="comparisons.tsv"','REFERENCE_REGISTRY="references.yaml"','source "/opt/conda_envs/microc2compare/site/shared-design-json-fix-20261008.conf"','```','','| Variable | Template default | Meaning |','|---|---|---|']
for key,definition in properties.items():
    if key.startswith('THREADS_'):description='Conservative '+key[8:].lower().replace('_',' ')+' worker/admission reservation; serial adapters may use less. Nested BLAS threads stay one.'
    elif key.startswith('MEMORY_MB_'):description='Decimal MB '+key[10:].lower().replace('_',' ')+' memory reservation; admission bound, not enforced RSS. Must fit the global budget.'
    else:description=DETAILS[key]
    default=definition['default']
    if isinstance(default,bool):default=str(default).lower()
    lines.append(f'| `{key}` | `{default}` | {description} |')
lines+=['','Optional flags do not imply new-map permission. Invalid required weights/resolutions fail with upstream remediation. Statistical policy floors cannot be weakened below three formal/two preliminary units and two residual df. Tuning scientific settings changes completion/calibration keys and requires a reviewed pilot; no setting proves adequate 5-kb coverage automatically.']
(ROOT/'docs/03-configuration.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
